#!/usr/bin/env python3
"""Run the preservation equivalence checks against one specified WASM build."""
import concurrent.futures,subprocess,os,json,pathlib,sys,hashlib
bundle=str(pathlib.Path(sys.argv[1]).resolve());prefix=sys.argv[2];groups=[('mapping_cache','test_mapping_cache_wasm'),('budget','test_budget_wasm'),('runtime','test_runtime'),('render_hot','test_render_hot_wasm'),('cvm_mark','test_cvm_mark_wasm'),('gc_graph','test_gc_graph_wasm'),('gc_banks','test_gc_banks_wasm'),('gc_collect','test_gc_collect_wasm'),('uniform','test_uniform_wasm'),('clear','test_clear_wasm'),('render_loop','test_render_loop_wasm'),('heap','test_heap_wasm'),('script_marks','test_script_marks_wasm'),('asset_hot','test_asset_hot_wasm'),('render_state','test_render_state_wasm'),('alloc','test_alloc_wasm'),('lookup','test_lookup_wasm'),('hot','test_hot_wasm'),('decompression','test_decompression_wasm'),('graphics_batch','test_graphics_batch'),('audio_frames','test_audio_frames_wasm'),('matrix','test_matrix_wasm'),('font','test_font_wasm'),('font_layout','test_font_layout_wasm'),('script_lookup','test_script_lookup_wasm'),('variant_refs','test_variant_refs_wasm'),('crypto','test_crypto_wasm'),('memmanager','test_memmanager_wasm'),('value_helpers','test_value_helpers_wasm'),('allocation_callbacks','test_allocation_callbacks_wasm'),('array_copy','test_array_copy_wasm'),('pose','test_pose_wasm'),('bbox','test_bbox_wasm'),('digest','test_digest_wasm'),('assoc_set','test_assoc_set_wasm'),('bone_matrices','test_bone_matrices_wasm'),('mesh_buffers','test_mesh_buffers_wasm'),('cipher_chain','test_cipher_chain_wasm'),('assoc_merge','test_assoc_merge_wasm'),('dynamic_vertices','test_dynamic_vertices_wasm'),('cleanup_vertices','test_cleanup_vertices_wasm'),('dynamic_bounds','test_dynamic_bounds_wasm'),('animation','test_animation_wasm'),('motion','test_motion_wasm'),('code_cache','test_code_cache_wasm'),('file_streams','test_file_streams_wasm'),('worker_handoff','test_worker_handoff_wasm'),('region','test_region_wasm'),('bytecode','test_bytecode_wasm'),('material','test_material_wasm'),('math','test_math_wasm'),('asset_lookup','test_asset_lookup_wasm'),('blackout','test_blackout_wasm'),('link','test_link_wasm'),('exit_gate','test_exit_gate_wasm')];env=dict(os.environ,OU_EMULATOR_BUNDLE=bundle,OU_RUNTIME_REPORT=prefix+'-runtime-tests.json',OU_HOT_REPORT=prefix+'-hot-tests.json')
pathlib.Path('analysis/'+prefix+'-semantic-build.json').write_text(json.dumps({'bundle':bundle,'bundle_sha256':hashlib.sha256(pathlib.Path(bundle).read_bytes()).hexdigest(),'runtime_sha256':{str(p):hashlib.sha256(p.read_bytes()).hexdigest()for p in pathlib.Path('port/runtime').glob('*.mjs')}},indent=2)+'\n')
def test(item):
 name,file=item;path='port/tests/'+file+'.mjs';assert 'OU_EMULATOR_BUNDLE' in pathlib.Path(path).read_text(),path;log='analysis/'+prefix+'-'+name+'-tests.log'
 with open(log,'w') as stream:r=subprocess.run(['node',path],env=env,stdout=stream,stderr=subprocess.STDOUT)
 return {'name':name,'exit_code':r.returncode,'log':log}
with concurrent.futures.ThreadPoolExecutor(4) as pool:results=list(pool.map(test,groups))
pathlib.Path('analysis/'+prefix+'-semantic-tests.json').write_text(json.dumps(results,indent=2)+'\n');print(json.dumps(results,indent=2));raise SystemExit(any(r['exit_code'] for r in results))
